float saturate(float x) {
    return min(1.0, max(0.0, x));
}

vec3 saturate(vec3 x) {
    return min(vec3(1.0), max(vec3(0.0), x));
}

vec3 bump3y(vec3 x, vec3 yoffset) {
    vec3 y = vec3(1.0) - x * x;
    y = saturate(y - yoffset);
    return y;
}

vec3 spectral_zucconi6(float w) {
    float x = saturate((w - 400.0) / 300.0);

    const vec3 c1 = vec3(3.54585104, 2.93225262, 2.41593945);
    const vec3 x1 = vec3(0.69549072, 0.49228336, 0.27699880);
    const vec3 y1 = vec3(0.02312639, 0.15225084, 0.52607955);

    const vec3 c2 = vec3(3.90307140, 3.21182957, 3.96587128);
    const vec3 x2 = vec3(0.11748627, 0.86755042, 0.66077860);
    const vec3 y2 = vec3(0.84897130, 0.88445281, 0.73949448);

    return bump3y(c1 * (x - x1), y1) + bump3y(c2 * (x - x2), y2);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / min(iResolution.x, iResolution.y);

    float angle = atan(uv.y, uv.x);
    float radius = length(uv);

    // Create star pattern with 8 points
    float star = abs(sin(angle * 4.0));
    float pattern = smoothstep(0.4 + star * 0.6, 0.0, radius);

    // Map pattern to wavelength (400-700nm)
    float wavelength = mix(400.0, 700.0, pattern);

    vec3 color = spectral_zucconi6(wavelength);
    fragColor = vec4(color, 1.0);
}
